mapper.select:
select ppos.*,pp.P_Name as pName,pp.P_Project_Form_Type pProjectFormType, pp.P_Competent_Department as pCompetentDepartment,sd.D_Name as pCompetentDepartmentName from pre_project_org_struct ppos left join Pre_Project pp on ppos.p_id=pp.P_ID left join SYS_Department sd on pp.P_Competent_Department = sd.D_ID
and ppos.p_id = #{pId}
and likePname(#{pName},pp.P_Id)=true
and pp.p_name like concat('%',#{pName},'%')
and pp.p_Competent_Department = #{pCompetentDepartment}
and sd.D_Name like concat('%',#{pCompetentDepartmentName},'%')
